const item = $input.first().json || {};

const workflow = item.workflow || item.workflowData || {};
const execution = item.execution || item.executionData || {};

const err =
  item.error ||
  execution.error ||
  item.execution?.error ||
  item.executionData?.error ||
  {};

const failedNode =
  err.node?.name ||
  err.nodeName ||
  execution.lastNodeExecuted ||
  item.lastNodeExecuted ||
  item.nodeName ||
  'unknown node';

const errorMessage =
  err.message ||
  err.description ||
  err.cause?.message ||
  item.errorMessage ||
  item.message ||
  (Object.keys(err).length ? JSON.stringify(err) : 'Unknown error');

const stack = err.stack || item.stack || '';

const israelTime = new Intl.DateTimeFormat('en-IL', {
  timeZone: 'Asia/Jerusalem',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false,
}).format(new Date());

const baseUrl = String($env.PUBLIC_N8N_BASE_URL || $env.N8N_EDITOR_BASE_URL || '').replace(/\/$/, '');

const workflowId = workflow.id || execution.workflowId || item.workflowId || 'unknown';
const workflowName = workflow.name || item.workflowName || 'Unknown workflow';
const executionId = execution.id || item.executionId || 'unknown';
const mode = execution.mode || item.mode || 'unknown';
const startedAt = execution.startedAt || item.startedAt || new Date().toISOString();

const executionUrl =
  baseUrl && workflowId !== 'unknown' && executionId !== 'unknown'
    ? `${baseUrl}/workflow/${workflowId}/executions/${executionId}`
    : '';

const responseBodyRaw =
  err.response?.body ??
  err.cause?.response?.body ??
  item.response?.body ??
  item.body?.responseBody ??
  item.responseBody ??
  '';

const responseBody =
  typeof responseBodyRaw === 'string'
    ? responseBodyRaw
    : responseBodyRaw
      ? JSON.stringify(responseBodyRaw)
      : '';

const responseBodyExcerpt =
  responseBody.length > 1200 ? `${responseBody.slice(0, 1200)}...` : responseBody;

const dlqPath = $env.N8N_ERROR_DLQ_PATH || '/files/dlq/n8n-errors.jsonl';

const record = {
  timestampIsrael: israelTime,
  timestampUtc: new Date().toISOString(),
  workflowId,
  workflowName,
  executionId,
  nodeName: failedNode,
  mode,
  startedAt,
  message: errorMessage,
  responseBody: responseBodyExcerpt,
  executionUrl,
  stack,
  rawErrorPayload: item,
};

const text = [
  'n8n workflow failure',
  `Time Israel: ${israelTime}`,
  `Workflow: ${workflowName}`,
  `Node: ${failedNode}`,
  `Execution: ${executionId}`,
  `Mode: ${mode}`,
  `Started UTC: ${startedAt}`,
  `Error: ${errorMessage}`,
  responseBodyExcerpt ? `Response body: ${responseBodyExcerpt}` : '',
  executionUrl ? `Open: ${executionUrl}` : '',
].filter(Boolean).join('\n');

const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(JSON.stringify(record) + '\n'),
  'error.jsonl',
  'text/plain'
);

return [{
  json: {
    ...record,
    dlqPath,
    telegramText: text,
    chatId: $env.TELEGRAM_ERROR_CHAT_ID || $env.TELEGRAM_APPROVAL_CHAT_ID,
  },
  binary: {
    data: binaryData,
  },
}];
